-- Initial Arkvoid schema. Apply only to a reviewed, fresh project. Names are prefixed to avoid legacy prototype tables.
create extension if not exists pgcrypto;
do $$ begin create type public.arkvoid_event_type as enum ('SPOKE','PROMISE_MADE','PROMISE_UPDATED','ITEM_GATHERED','ITEM_GIVEN','MOVED','WORK_STARTED','WORK_COMPLETED','TRAINED','BREAKTHROUGH','TRUST_CHANGED','SIGHTED','NOTE'); exception when duplicate_object then null; end $$;
create table if not exists public.arkvoid_profiles(id uuid primary key references auth.users(id) on delete cascade, handle text unique, display_name text not null default 'Wanderer' check(char_length(display_name) between 1 and 40), is_guest boolean not null default false, role text not null default 'player' check(role in ('player','creator','moderator','admin')), created_at timestamptz not null default now());
create table if not exists public.arkvoid_characters(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.arkvoid_profiles(id) on delete cascade,name text not null check(char_length(name) between 2 and 24),path text not null check(path in ('Wayfarer','Keeper','Seeker')),appearance jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists public.arkvoid_worlds(id uuid primary key default gen_random_uuid(),owner_character_id uuid not null unique references public.arkvoid_characters(id) on delete cascade,kind text not null default 'home' check(kind='home'),created_at timestamptz not null default now());
alter table public.arkvoid_characters add column if not exists world_id uuid references public.arkvoid_worlds(id) on delete set null;
create table if not exists public.arkvoid_world_state(world_id uuid primary key references public.arkvoid_worlds(id) on delete cascade,now_minute bigint not null default 1085,last_seen_real timestamptz not null default now(),place text not null default 'east-gate',flags jsonb not null default '{}'::jsonb,version integer not null default 1);
create table if not exists public.arkvoid_ledger_events(id bigserial primary key,world_id uuid not null references public.arkvoid_worlds(id) on delete cascade,t bigint not null,type public.arkvoid_event_type not null,actors text[] not null default '{}',place text not null default 'east-gate',data jsonb not null default '{}'::jsonb,importance smallint not null default 1 check(importance between 1 and 5),summary text not null check(char_length(summary) between 1 and 280),created_at timestamptz not null default now());
alter table public.arkvoid_profiles enable row level security; alter table public.arkvoid_characters enable row level security; alter table public.arkvoid_worlds enable row level security; alter table public.arkvoid_world_state enable row level security; alter table public.arkvoid_ledger_events enable row level security;
drop policy if exists arkvoid_profile_self_read on public.arkvoid_profiles; create policy arkvoid_profile_self_read on public.arkvoid_profiles for select to authenticated using(id=auth.uid());
drop policy if exists arkvoid_character_self_read on public.arkvoid_characters; create policy arkvoid_character_self_read on public.arkvoid_characters for select to authenticated using(user_id=auth.uid());
drop policy if exists arkvoid_world_owner_read on public.arkvoid_worlds; create policy arkvoid_world_owner_read on public.arkvoid_worlds for select to authenticated using(exists(select 1 from public.arkvoid_characters c where c.id=owner_character_id and c.user_id=auth.uid()));
drop policy if exists arkvoid_state_owner_read on public.arkvoid_world_state; create policy arkvoid_state_owner_read on public.arkvoid_world_state for select to authenticated using(exists(select 1 from public.arkvoid_worlds w join public.arkvoid_characters c on c.id=w.owner_character_id where w.id=world_id and c.user_id=auth.uid()));
drop policy if exists arkvoid_ledger_owner_read on public.arkvoid_ledger_events; create policy arkvoid_ledger_owner_read on public.arkvoid_ledger_events for select to authenticated using(exists(select 1 from public.arkvoid_worlds w join public.arkvoid_characters c on c.id=w.owner_character_id where w.id=world_id and c.user_id=auth.uid()));
revoke insert,update,delete on public.arkvoid_ledger_events from anon,authenticated; grant select on public.arkvoid_ledger_events,public.arkvoid_worlds,public.arkvoid_world_state,public.arkvoid_characters,public.arkvoid_profiles to authenticated;
